  // style-service
  const StyleService = {
    pending: new Map(),

    ensure(id, css) {
      const styleId = String(id || '').trim();
      if (!styleId) throw new TypeError('Style id is required');

      const existing = document.getElementById(styleId);
      if (existing) return existing;
      if (this.pending.has(styleId)) return this.pending.get(styleId);

      const style = document.createElement('style');
      style.id = styleId;
      style.textContent = String(css || '');
      this.pending.set(styleId, style);

      const mount = () => {
        if (!document.getElementById(styleId)) document.head?.appendChild(style);
        this.pending.delete(styleId);
      };
      if (document.head) mount();
      else document.addEventListener('DOMContentLoaded', mount, {once: true});
      return style;
    }
  };

  // game-ui-adapter
  function createGameUiAdapter() {
    const GameUiAdapter = {
      selectors: {
        housePanel: '[class*="HousePanel_housePanel__"]',
        houseButtonContainer: '[class*="HousePanel_buttonContainer__"]',
        houseTitle: '[class*="HousePanel_title__"]',
        labyrinthPanel: '[class*="LabyrinthPanel_labyrinthPanel__"]',
        labyrinthEntryScreen: '[class*="LabyrinthPanel_entryScreen__"]',
        labyrinthButtonsContainer: '[class*="LabyrinthPanel_buttonsContainer__"]',
        marketplaceNavButtons: '[class*="MarketplacePanel_marketNavButtonContainer__"]',
        // 物品掛牌頁（訂單簿檢視）的訂單簿容器：作為「當前是訂單簿檢視」的判據（物品摘要檢視沒有它）。
        marketOrderBooks: '[class*="MarketplacePanel_orderBooksContainer__"]',
        // 掛牌按鈕行（「+ 新出售掛牌 / + 新購買掛牌」，display: flex + space-between）：
        // 模組把這一行設為相對定位錨點，兩側的最近成交提示條相對它絕對定位。
        marketNewListingButtons: '[class*="MarketplacePanel_newListingButtonsContainer__"]',
        // 市場主標籤欄（「商品列表 / 我的掛牌」所在行，display: flex，與標籤同排）。
        marketplaceTabs: '[class*="MarketplacePanel_tabsComponentContainer__"]',
        // 主標籤按鈕所在的 MUI flex 行；優先匹配使用者實測的 MarketplacePanel 直接子級，
        // 再相容當前遊戲原始碼中的 TabsComponent 巢狀層級。
        marketplaceTabBar: '[class*="MarketplacePanel_marketplacePanel__"] > .MuiTabs-flexContainer',
        marketplaceTabBarNested: '[class*="MarketplacePanel_tabsComponentContainer__"] .MuiTabs-flexContainer',
        marketplaceTabBarLegacy:
          '[class*="MarketplacePanel_tabsComponentContainer__"] [class*="TabsComponent_tabsContainer__"]',
        equipmentPanel: '[class*="EquipmentPanel_equipmentPanel__"]',
        equipmentButtonContainer: '[class*="EquipmentPanel_buttonContainer__"]',
        selectedLoadout: '[class*="LoadoutsPanel_selectedLoadout__"]',
        loadoutDetails: '[class*="LoadoutsPanel_details__"], [class*="details"]',
        loadoutMetadata: '[class*="LoadoutsPanel_metadata__"], [class*="metadata"]',
        characterName: '[class*="CharacterName_characterName__"]',
        header: '[class*="Header_header__"]',
        headerCharacterInfo: '[class*="Header_characterInfo"]',
        headerNameData: '[class*="Header_name"] [data-name]',
        gameButton: 'button[class*="Button_button__"]'
      },

      query(name, root = document) {
        const selector = this.selectors[name];
        if (!selector || !root?.querySelectorAll) return null;
        return [
            ...root.querySelectorAll(selector)
          ].find((element) => !element.closest('.mst-character-card-modal, .mst-skill-selector-modal')) || null;
      },

      queryAll(name, root = document) {
        const selector = this.selectors[name];
        if (!selector || !root?.querySelectorAll) return [];
        return [
          ...root.querySelectorAll(selector)
        ].filter((element) => !element.closest('.mst-character-card-modal, .mst-skill-selector-modal'));
      }
    };

    return GameUiAdapter;
  }

  // sprite-service
  function createSpriteService() {
    const SpriteService = {
      defaults: {
        items: '/static/media/items_sprite.f58c9476.svg',
        skills: '/static/media/skills_sprite.3bb4d936.svg',
        abilities: '/static/media/abilities_sprite.fdd1b4de.svg',
        actions: '/static/media/actions_sprite.e6388cbc.svg',
        misc: '/static/media/misc_sprite.02869244.svg',
        chatIcons: '/static/media/chat_icons_sprite.5a021815.svg'
      },
      markers: {
        items: 'items_sprite',
        skills: 'skills_sprite',
        abilities: 'abilities_sprite',
        actions: 'actions_sprite',
        misc: 'misc_sprite',
        chatIcons: 'chat_icons_sprite'
      },
      paths: new Map(),
      domRevision: 0,
      scannedRevision: -1,

      getUseHref(useElement) {
        return useElement?.getAttribute('href') || useElement?.getAttribute('xlink:href') || '';
      },

      markDomChanged() {
        this.domRevision += 1;
      },

      refresh() {
        this.scannedRevision = -1;
        this.scanPage();
      },

      scanPage() {
        if (this.scannedRevision === this.domRevision) return;
        this.scannedRevision = this.domRevision;
        // 同一 sprite 在頁面上可能有多個檔名：其它指令碼（如第三方懸浮面板）還在用舊 hash，
        // 而遊戲自己渲染的圖示數量遠多於它們，因此取出現次數最多的一個；數量並列時優先
        // 遊戲根容器（#root）內的寫法，避免誤用第三方指令碼的舊圖示集。
        const types = Object.entries(this.markers);
        const counts = new Map();
        for (const useElement of document.querySelectorAll('svg use')) {
          const href = this.getUseHref(useElement);
          if (!href.includes('#')) continue;
          const spritePath = href.split('#')[0];
          const match = types.find(
            ([
              , marker
            ]) => spritePath.includes(marker)
          );
          if (!match) continue;
          const [
            type
          ] = match;
          let perPath = counts.get(type);
          if (!perPath) counts.set(type, (perPath = new Map()));
          const entry = perPath.get(spritePath) || {path: spritePath, count: 0, inRoot: false};
          entry.count += 1;
          entry.inRoot = entry.inRoot || Boolean(useElement.closest?.('#root'));
          perPath.set(spritePath, entry);
        }
        this.paths.clear();
        for (const [
          type, perPath
        ] of counts) {
          let best = null;
          for (const entry of perPath.values()) {
            if (!best || entry.count > best.count || (entry.count === best.count && entry.inRoot && !best.inRoot)) {
              best = entry;
            }
          }
          if (best) this.paths.set(type, best.path);
        }
      },

      get(spriteName) {
        const name = String(spriteName || '').replace(/_sprite$/, '');
        const type = name === 'chat_icons' ? 'chatIcons' : name;
        if (!this.markers[type]) return '';
        this.scanPage();
        return this.paths.get(type) || this.defaults[type] || '';
      }
    };

    return SpriteService;
  }

  // dom-observer-service
  function createDomObserverService(SpriteService) {
    const DomObserverService = {
      subscribers: new Set(),
      observer: null,
      scheduled: false,
      waitingForBody: false,
      options: {childList: true, subtree: true},

      runCallbacks(callbacks) {
        if (!document.body || !callbacks.length) return;
        this.observer?.disconnect();
        try {
          callbacks.forEach((callback) => {
            try {
              callback();
            } catch (error) {
              console.error('[MST] DOM observer callback failed:', error);
            }
          });
        } finally {
          this.observe();
        }
      },

      observe() {
        if (!document.body || !this.subscribers.size) return;
        if (!this.observer) {
          this.observer = new MutationObserver(() => {
            SpriteService.markDomChanged();
            this.schedule();
          });
        }
        this.observer.observe(document.body, this.options);
      },

      schedule() {
        if (this.scheduled || !this.subscribers.size) return;
        this.scheduled = true;
        const runCallbacks = () => {
          this.scheduled = false;
          this.runCallbacks([
            ...this.subscribers
          ]);
        };
        if (window.requestAnimationFrame) window.requestAnimationFrame(runCallbacks);
        else setTimeout(runCallbacks, 0);
      },

      handleBodyReady() {
        this.waitingForBody = false;
        this.runCallbacks([
          ...this.subscribers
        ]);
      },

      subscribe(callback) {
        if (typeof callback !== 'function') throw new TypeError('DOM observer callback must be a function');
        this.subscribers.add(callback);
        if (document.body) {
          this.runCallbacks([
            callback
          ]);
        } else if (!this.waitingForBody) {
          this.waitingForBody = true;
          document.addEventListener('DOMContentLoaded', this.handleBodyReady.bind(this), {once: true});
        }
        let disconnected = false;
        return {
          disconnect: () => {
            if (disconnected) return;
            disconnected = true;
            this.subscribers.delete(callback);
            if (!this.subscribers.size) this.observer?.disconnect();
          }
        };
      }
    };

    // ==================== 公共工具 ====================

    return DomObserverService;
  }

  // gm-api
  function createGmApi() {
    const getModernApi = (name) =>
      typeof GM !== 'undefined' && typeof GM?.[name] === 'function' ? GM[name].bind(GM) : null;

    const GmApi = {
      getValueApi() {
        if (typeof GM_getValue === 'function') return GM_getValue;
        return getModernApi('getValue');
      },

      setValueApi() {
        if (typeof GM_setValue === 'function') return GM_setValue;
        return getModernApi('setValue');
      },

      addValueChangeListenerApi() {
        if (typeof GM_addValueChangeListener === 'function') return GM_addValueChangeListener;
        return getModernApi('addValueChangeListener');
      },

      xmlHttpRequestApi() {
        if (typeof GM_xmlhttpRequest === 'function') return GM_xmlhttpRequest;
        return getModernApi('xmlHttpRequest');
      },

      setClipboardApi() {
        if (typeof GM_setClipboard === 'function') return GM_setClipboard;
        return getModernApi('setClipboard');
      },

      async getValue(key, defaultValue = undefined) {
        const getValue = this.getValueApi();
        return getValue ? getValue(key, defaultValue) : defaultValue;
      },

      setValue(key, value) {
        const setValue = this.setValueApi();
        return setValue ? setValue(key, value) : undefined;
      },

      addValueChangeListener(key, callback) {
        const addValueChangeListener = this.addValueChangeListenerApi();
        return addValueChangeListener ? addValueChangeListener(key, callback) : null;
      },

      xmlHttpRequest(details) {
        const request = this.xmlHttpRequestApi();
        return request ? request(details) : null;
      },

      setClipboard(text, type = 'text') {
        const setClipboard = this.setClipboardApi();
        return setClipboard ? setClipboard(String(text), type) : undefined;
      }
    };

    return GmApi;
  }

  // page-bridge-service
  function createPageBridgeService(ctx) {
    const {pageWindow} = ctx;

    const PageBridgeService = {
      installed: new Set(),
      errors: new Map(),
      sequence: 0,

      install({key, source, label = key}) {
        if (!key || !source) throw new TypeError('Page bridge key and source are required');
        if (this.installed.has(key)) return true;
        try {
          if (typeof pageWindow?.Function !== 'function') throw new Error('pageWindow.Function is not available');
          pageWindow.Function(String(source))();
          this.installed.add(key);
          this.errors.delete(key);
          return true;
        } catch (error) {
          this.errors.set(key, error?.message || String(error));
        }
        try {
          const script = document.createElement('script');
          script.textContent = String(source);
          (document.head || document.documentElement).appendChild(script);
          script.remove();
          this.installed.add(key);
          this.errors.delete(key);
          return true;
        } catch (error) {
          const message = error?.message || String(error);
          this.errors.set(key, message);
          console.warn('[MST] 安裝頁面橋失敗:', {label, error: message});
          return false;
        }
      },

      getError(key) {
        return this.errors.get(key) || '';
      },

      request({requestEvent, responseEvent, payload = {}, idPrefix = 'mst-bridge'}) {
        const id = idPrefix + '-' + ++this.sequence;
        let result = null;
        const handleResponse = (event) => {
          try {
            const detail = JSON.parse(String(event.detail || '{}'));
            if (detail.id === id) result = detail;
          } catch {}
        };
        window.addEventListener(responseEvent, handleResponse);
        window.dispatchEvent(new CustomEvent(requestEvent, {detail: JSON.stringify({id, ...payload})}));
        window.removeEventListener(responseEvent, handleResponse);
        return result;
      }
    };

    return PageBridgeService;
  }

  // runtime-utils
  function createRuntimeUtils(ctx, {SpriteService, DomObserverService}) {
    const {DataHub, GmApi, i18n} = ctx;

    const utils = {
      substrLastSlash(hrid) {
        return String(hrid || '').substring(String(hrid || '').lastIndexOf('/') + 1);
      },

      getSvgUseHref(useElement) {
        return SpriteService.getUseHref(useElement);
      },

      getSvgSpriteUrl(useSelector) {
        const href = this.getSvgUseHref(document.querySelector(useSelector));
        return href.includes('#') ? href.split('#')[0] : '';
      },

      getSpriteUrl(spriteName) {
        return SpriteService.get(spriteName);
      },

      clampLevel(value, min, max) {
        const num = parseInt(value, 10);
        if (Number.isNaN(num)) return min;
        return Math.min(max, Math.max(min, num));
      },

      getCollectionValues(collection) {
        if (Array.isArray(collection)) return collection;
        if (collection instanceof Map) return [
            ...collection.values()
          ];
        if (collection && typeof collection === 'object') return Object.values(collection);
        return [];
      },

      normalizeItemHrid(value) {
        const itemId = String(value || '')
          .replace(/^#/, '')
          .replace(/^\/items\//, '');
        return itemId ? '/items/' + itemId : '';
      },

      normalizeItemId(itemHrid) {
        return String(itemHrid || '').replace(/^\/items\//, '');
      },

      getItemName(itemHrid) {
        const itemId = this.normalizeItemId(itemHrid);
        const fallback = itemId.replace(/_/g, ' ');
        return DataHub.resolveItemName(itemHrid) || fallback;
      },

      getHouseName(hrid) {
        const room = DataHub.getHouseDetail(hrid);
        const langMap = {
          zh: DataHub.clientData.indexes.houseHridToNameZh,
          en: DataHub.clientData.indexes.houseHridToNameEn
        }[i18n.languageKey];
        return langMap?.get(hrid) || room?.name || hrid;
      },

      getReactProps(el) {
        const key = Reflect.ownKeys(el || {}).find((k) => String(k).startsWith('__reactProps'));
        return key ? el[key] : null;
      },

      getReactComponentProps(el) {
        const props = this.getReactProps(el);
        return props?.children?.[0]?._owner?.memoizedProps || props?._owner?.memoizedProps || props || null;
      },

      getItemByHash(hash) {
        const parts = String(hash || '').split('::');
        if (parts.length !== 4) return null;
        return {itemHrid: parts[2], enhancementLevel: Number(parts[3]) || 0};
      },

      getTextBetween(start, end) {
        let text = '';
        let current = start?.nextSibling;
        while (current && current !== end) {
          if (current.nodeType === Node.TEXT_NODE) text += current.textContent || '';
          current = current.nextSibling;
        }
        return text;
      },

      async writeClipboard(text) {
        if (GmApi?.setClipboardApi()) {
          await GmApi.setClipboard(String(text), 'text');
          return;
        }
        if (!navigator.clipboard?.writeText) throw new Error(i18n.t('clipboardUnavailable'));
        await navigator.clipboard.writeText(String(text));
      },

      async readClipboard() {
        if (!navigator.clipboard?.readText) throw new Error(i18n.t('clipboardUnavailable'));
        return navigator.clipboard.readText();
      },

      formatMarketTime(timestamp) {
        if (!timestamp) return i18n.t('marketNoData');
        const date = new Date(timestamp * 1000);
        const y = date.getFullYear();
        const m = String(date.getMonth() + 1).padStart(2, '0');
        const d = String(date.getDate()).padStart(2, '0');
        const hh = String(date.getHours()).padStart(2, '0');
        const mm = String(date.getMinutes()).padStart(2, '0');
        return y + '.' + m + '.' + d + ' ' + hh + ':' + mm;
      },

      formatLocalFileTime(date = new Date()) {
        const y = date.getFullYear();
        const m = String(date.getMonth() + 1).padStart(2, '0');
        const d = String(date.getDate()).padStart(2, '0');
        const hh = String(date.getHours()).padStart(2, '0');
        const mm = String(date.getMinutes()).padStart(2, '0');
        const ss = String(date.getSeconds()).padStart(2, '0');
        return y + m + d + '-' + hh + mm + ss;
      },

      formatCompactNumber(value, maximumFractionDigits = 2) {
        const number = Number(value);
        if (!Number.isFinite(number)) return '-';
        const units = [
          {value: 1e12, suffix: 'T'}, {value: 1e9, suffix: 'B'}, {value: 1e6, suffix: 'M'}, {value: 1e3, suffix: 'K'}
        ];
        const unit = units.find((entry) => Math.abs(number) >= entry.value);
        const scaled = unit ? number / unit.value : number;
        const formatted = scaled.toLocaleString(undefined, {maximumFractionDigits, minimumFractionDigits: 0});
        return formatted + (unit?.suffix || '');
      },

      // 遊戲市場的價格寫法（對照遊戲原始碼 main chunk 的 formatMarketplacePrice，常量 K/M/B/T 與 EPSILON=1e-9）：
      // 10 萬以下顯示整數（不帶千位分隔符），10 萬 / 1000 萬 / 100 億 / 10 萬億起換算 K / M / B / T 字尾，
      // 換算後不足 100 保留兩位、不足 1000 保留一位、再大取整。市場裡的掛單價、可交易區間、
      // 商品列表價格都走這套寫法，掛牌頁速覽的單價必須與之一致。
      formatMarketplacePrice(value) {
        // 與遊戲一致的換算誤差補償（遊戲常量 EPSILON = 1e-9），避免浮點尾差把整數檔算少 1。
        const EPSILON = 1e-9;
        const number = Number(value) || 0;
        const abs = Math.abs(number);
        const K = 1e3;
        const M = 1e6;
        const B = 1e9;
        const T = 1e12;
        let scaled = number;
        let suffix = '';
        if (abs < 100 * K) scaled = Math.sign(number) * Math.floor(abs);
        else if (abs < 10 * M) {
          scaled = number / K;
          suffix = 'K';
        } else if (abs < 10 * B) {
          scaled = number / M;
          suffix = 'M';
        } else if (abs < 10 * T) {
          scaled = number / B;
          suffix = 'B';
        } else if (abs <= 1e3 * T) {
          scaled = number / T;
          suffix = 'T';
        } else return 'Lots!';
        if (suffix) {
          const scaledAbs = Math.abs(scaled);
          const digits = scaledAbs < 100 ? 2 : scaledAbs < 1e3 ? 1 : 0;
          const factor = 10 ** digits;
          scaled = (Math.sign(scaled) * Math.floor((scaledAbs + EPSILON) * factor)) / factor;
        }
        return String(scaled) + suffix;
      },

      formatDateTime(value) {
        const date = value instanceof Date ? value : new Date(value);
        if (Number.isNaN(date.getTime())) return '-';
        return date.toLocaleString(i18n.locale, {
          year: 'numeric',
          month: '2-digit',
          day: '2-digit',
          hour: '2-digit',
          minute: '2-digit'
        });
      },

      getGameButtonClass() {
        const button = document.querySelector('button[class*="Button_button"]');
        return [
            ...(button?.classList || [])
          ].find((className) => className.startsWith('Button_button')) || 'Button_button__1Fe9z';
      },

      createLevelOptions(min, max, selected) {
        let html = '';
        for (let level = min; level <= max; level++) {
          html += '<option value="' + level + '"' + (level === selected ? ' selected' : '') + '>' + level + '</option>';
        }
        return html;
      },

      escapeHtml(value) {
        return String(value ?? '')
          .replace(/&/g, '&amp;')
          .replace(/</g, '&lt;')
          .replace(/>/g, '&gt;')
          .replace(/"/g, '&quot;')
          .replace(/'/g, '&#39;');
      },

      ensureButton({host, id, text, title = '', className = '', prepend = false, onClick}) {
        if (!host) return null;
        const existing = id ? document.getElementById(id) : null;
        if (existing) return existing;
        const button = document.createElement('button');
        if (id) button.id = id;
        if (className) button.className = className;
        button.type = 'button';
        button.textContent = text;
        if (title) button.title = title;
        if (typeof onClick === 'function') button.addEventListener('click', onClick);
        if (prepend) host.prepend(button);
        else host.appendChild(button);
        return button;
      },

      observeBody(callback) {
        return DomObserverService.subscribe(callback);
      }
    };

    return utils;
  }

  // game-navigation-service
  function createGameNavigationService(ctx) {
    const {DataHub, pageWindow, PageBridgeService, utils} = ctx;

    const GameNavigationService = {
      bridgeInstalled: false,
      bridgeInstallError: '',

      installPageBridge() {
        if (this.bridgeInstalled) return true;
        const source = `
        (() => {
          if (window.__MST_NAV_BRIDGE_INSTALLED__) return;
          const getFiber = (element) => {
            const key = Reflect.ownKeys(element || {}).find((item) => String(item).startsWith('__reactFiber$'));
            return key ? element[key] : null;
          };
          const findHostFromFiber = (fiber) => {
            let current = fiber;
            while (current) {
              const host = current.stateNode;
              if (
                host &&
                typeof host === 'object' &&
                (typeof host.handleSwitchCharacter === 'function' ||
                  typeof host.handleGoToMarketplace === 'function')
              ) {
                return host;
              }
              current = current.return;
            }
            return null;
          };
          const getCandidates = () => {
            const selectors = [
              '[class*="GamePage_gamePage__"]', '[class*="GamePage_gamePanel__"]',
              '[class*="GamePage_contentPanel__"]', '[class*="Header_header__"]', '[class^="GamePage"]', '#root'
            ];
            const nodes = [];
            selectors.forEach((selector) => {
              document.querySelectorAll(selector).forEach((node) => nodes.push(node));
            });
            if (!nodes.length) {
              document.querySelectorAll('[class]').forEach((node) => nodes.push(node));
            }
            return [...new Set(nodes)];
          };
          const findHost = () => {
            if (window.mwiHelper?.game) return window.mwiHelper.game;
            if (window.mwi?.game) return window.mwi.game;
            for (const node of getCandidates()) {
              const host = findHostFromFiber(getFiber(node));
              if (host) return host;
            }
            return null;
          };
          const getDiagnostics = () => {
            const candidates = getCandidates();
            const candidateSummary = candidates.slice(0, 30).map((node) => ({
              tagName: node.tagName || '',
              className: String(node.className || '').slice(0, 180),
              hasFiber: Boolean(getFiber(node))
            }));
            const host = findHost();
            const hostKeys = host ? Reflect.ownKeys(host).map(String).sort() : [];
            return {
              pageContext: true,
              hasHost: Boolean(host),
              hostConstructor: host?.constructor?.name || '',
              hostKeys,
              functionKeys: hostKeys.filter((key) => typeof host?.[key] === 'function'),
              hasSwitchCharacter: typeof host?.handleSwitchCharacter === 'function',
              hasGoToMarketplace: typeof host?.handleGoToMarketplace === 'function',
              candidateCount: candidates.length,
              candidateSummary
            };
          };
          window.__MST_NAV_BRIDGE__ = {
            getDiagnostics,
            switchCharacter() {
              const host = findHost();
              if (typeof host?.handleSwitchCharacter !== 'function') return {ok: false, diagnostics: getDiagnostics()};
              host.handleSwitchCharacter.call(host);
              return {ok: true, diagnostics: getDiagnostics()};
            },
            openMarketplace(itemHrid, enhancementLevel) {
              const host = findHost();
              if (typeof host?.handleGoToMarketplace !== 'function') return {ok: false, diagnostics: getDiagnostics()};
              host.handleGoToMarketplace.call(host, itemHrid, Number(enhancementLevel) || 0);
              return {ok: true, diagnostics: getDiagnostics()};
            }
          };
          const respond = (id, action, result) => {
            window.dispatchEvent(new CustomEvent('mst:navigation:result', {
              detail: JSON.stringify({id, action, ...result})
            }));
          };
          window.addEventListener('mst:navigation:switch-character', (event) => {
            const detail = JSON.parse(String(event.detail || '{}'));
            respond(detail.id, 'switchCharacter', window.__MST_NAV_BRIDGE__.switchCharacter());
          });
          window.addEventListener('mst:navigation:open-marketplace', (event) => {
            const detail = JSON.parse(String(event.detail || '{}'));
            respond(
              detail.id,
              'openMarketplace',
              window.__MST_NAV_BRIDGE__.openMarketplace(detail.itemHrid, detail.enhancementLevel)
            );
          });
          window.__MST_NAV_BRIDGE_INSTALLED__ = true;
        })();
      `;
        this.bridgeInstalled = PageBridgeService.install({
          key: 'navigation',
          label: '頁面原生跳轉橋',
          source
        });
        this.bridgeInstallError = PageBridgeService.getError('navigation');
        return this.bridgeInstalled;
      },

      dispatchBridgeAction(action, payload = {}) {
        if (!this.installPageBridge()) return null;
        const eventName =
          action === 'switchCharacter' ? 'mst:navigation:switch-character' : 'mst:navigation:open-marketplace';
        return PageBridgeService.request({
          requestEvent: eventName,
          responseEvent: 'mst:navigation:result',
          idPrefix: 'mst-nav',
          payload
        });
      },

      getHost() {
        let host = null;
        try {
          host = DataHub.getGameObject();
        } catch (error) {
          console.warn('[MST] 讀取遊戲原生入口物件失敗:', {error: error?.message || String(error)});
          return null;
        }
        return host && typeof host === 'object' ? host : null;
      },

      getHostDiagnostics(action, extra = {}) {
        const host = this.getHost();
        const read = (getter, fallback) => {
          try {
            return getter();
          } catch (error) {
            return fallback ?? '[read failed] ' + (error?.message || String(error));
          }
        };
        let hostKeys = [];
        let functionKeys = [];
        let hostReadError = '';
        try {
          hostKeys = host ? Reflect.ownKeys(host).map(String).sort() : [];
          functionKeys = hostKeys.filter((key) => {
            try {
              return typeof host?.[key] === 'function';
            } catch {
              return false;
            }
          });
        } catch (error) {
          hostReadError = error?.message || String(error);
        }
        const marketMate = read(() => pageWindow.MWITools?.shopping, null);
        return {
          action,
          characterId: DataHub.characterData?.raw?.character?.id ?? null,
          hasHost: Boolean(host),
          bridgeInstalled: this.bridgeInstalled,
          bridgeInstallError: this.bridgeInstallError,
          hostConstructor: read(() => host?.constructor?.name || '', ''),
          hostKeys,
          functionKeys,
          hostReadError,
          hasSwitchCharacter: read(() => typeof host?.handleSwitchCharacter === 'function', false),
          hasGoToMarketplace: read(() => typeof host?.handleGoToMarketplace === 'function', false),
          marketMateReady: read(() => marketMate?.ready === true, false),
          hasMarketMateOpenMarketplace: read(() => typeof marketMate?.openMarketplace === 'function', false),
          location: window.location.href,
          ...extra
        };
      },

      warnUnavailable(action, extra = {}) {
        console.warn('[MST] 未找到遊戲原生跳轉入口:', this.getHostDiagnostics(action, extra));
      },

      switchCharacter() {
        const bridgeResult = this.dispatchBridgeAction('switchCharacter');
        if (bridgeResult?.ok) return true;
        if (bridgeResult && !bridgeResult.ok) {
          this.warnUnavailable('switchCharacter', {bridgeDiagnostics: bridgeResult.diagnostics || null});
          return false;
        }
        const host = this.getHost();
        let switchCharacter = null;
        try {
          switchCharacter = typeof host?.handleSwitchCharacter === 'function' ? host.handleSwitchCharacter : null;
        } catch (error) {
          this.warnUnavailable('switchCharacter', {accessError: error?.message || String(error)});
          return false;
        }
        if (!switchCharacter) {
          this.warnUnavailable('switchCharacter', {bridgeNoResponse: this.bridgeInstalled});
          return false;
        }
        switchCharacter.call(host);
        return true;
      },

      openMarketplace(itemHrid, enhancementLevel = 0) {
        const fullHrid = utils.normalizeItemHrid(itemHrid);
        if (!fullHrid) return false;
        const bridgeResult = this.dispatchBridgeAction('openMarketplace', {
          itemHrid: fullHrid,
          enhancementLevel: Number(enhancementLevel) || 0
        });
        if (bridgeResult?.ok) return true;
        if (bridgeResult && !bridgeResult.ok) {
          this.warnUnavailable('openMarketplace', {
            itemHrid,
            fullHrid,
            enhancementLevel: Number(enhancementLevel) || 0,
            bridgeDiagnostics: bridgeResult.diagnostics || null
          });
          return false;
        }
        const host = this.getHost();
        let goToMarketplace = null;
        try {
          goToMarketplace = typeof host?.handleGoToMarketplace === 'function' ? host.handleGoToMarketplace : null;
        } catch (error) {
          this.warnUnavailable('openMarketplace', {itemHrid, fullHrid, accessError: error?.message || String(error)});
          return false;
        }
        if (goToMarketplace) {
          goToMarketplace.call(host, fullHrid, Number(enhancementLevel) || 0);
          return true;
        }
        let marketMate = null;
        try {
          marketMate = pageWindow.MWITools?.shopping;
          if (marketMate?.ready === true && typeof marketMate.openMarketplace === 'function') {
            // MWITools 的簽名是 (itemHrid, enhancementLevel = 0)：必須帶上強化等級，
            // 否則物品頁按等級取訂單簿時對不上、一直停在「正在載入」。
            return marketMate.openMarketplace(fullHrid, Number(enhancementLevel) || 0) === true;
          }
        } catch (error) {
          this.warnUnavailable('openMarketplace', {itemHrid, fullHrid, accessError: error?.message || String(error)});
          return false;
        }
        this.warnUnavailable('openMarketplace', {
          itemHrid,
          fullHrid,
          enhancementLevel: Number(enhancementLevel) || 0,
          bridgeNoResponse: this.bridgeInstalled
        });
        return false;
      }
    };

    return GameNavigationService;
  }

  // market-mate-bridge
  function createMarketMateBridge(ctx) {
    const {pageWindow} = ctx;

    const MarketMateBridge = {
      callbacks: new Set(),
      timer: null,
      attempts: 0,

      getApi() {
        // 市場伴侶已整合進 MWITools，通過 window.MWITools.shopping 提供購物車 API。
        const api = pageWindow.MWITools?.shopping;
        return api && typeof api.addToCart === 'function' ? api : null;
      },

      isReady() {
        return this.getApi()?.ready === true;
      },

      addToCart(items) {
        const api = this.getApi();
        if (!api?.ready) return {ok: false, added: 0, skipped: Array.isArray(items) ? items.length : 1};
        return api.addToCart(items);
      },

      onReady(callback) {
        if (typeof callback !== 'function') return;
        if (this.isReady()) {
          callback(this.getApi());
          return;
        }
        this.callbacks.add(callback);
        if (this.timer) return;
        this.attempts = 0;
        this.timer = setInterval(() => {
          this.attempts++;
          if (this.isReady()) {
            clearInterval(this.timer);
            this.timer = null;
            const api = this.getApi();
            const callbacks = [
              ...this.callbacks
            ];
            this.callbacks.clear();
            callbacks.forEach((fn) => fn(api));
          } else if (this.attempts >= 120) {
            clearInterval(this.timer);
            this.timer = null;
            this.callbacks.clear();
          }
        }, 1000);
      }
    };

    return MarketMateBridge;
  }

  // runtime-helpers
  function installRuntimeHelpers(ctx) {
    const GmApi = createGmApi();
    const PageBridgeService = ctx.PageBridgeService || createPageBridgeService(ctx);
    const GameUiAdapter = createGameUiAdapter();
    const SpriteService = createSpriteService();
    const DomObserverService = createDomObserverService(SpriteService);
    ctx.GmApi = GmApi;
    ctx.PageBridgeService = PageBridgeService;
    const utils = createRuntimeUtils(ctx, {SpriteService, DomObserverService});
    ctx.utils = utils;
    const GameNavigationService = createGameNavigationService(ctx);
    const MarketMateBridge = createMarketMateBridge(ctx);

    ctx.GameUiAdapter = GameUiAdapter;
    ctx.SpriteService = SpriteService;
    ctx.DomObserverService = DomObserverService;
    ctx.GameNavigationService = GameNavigationService;
    ctx.MarketMateBridge = MarketMateBridge;
  }

  // template-renderer
  const TemplateRenderer = {
    _html: null,
    _svg: null,
    _render: null,
    _Hole: null,
    _unsafe: null,
    _roots: new WeakMap(),
    ready: null,

    init() {
      if (this.ready) return this.ready;
      // uhtml 由 userscript @require 注入；不同指令碼沙箱可能只能通過全域性屬性讀取。
      const module = globalThis.uhtml || (typeof uhtml !== 'undefined' ? uhtml : null);
      if (!module) {
        this.ready = Promise.reject(new Error('uhtml @require is not ready'));
        return this.ready;
      }
      this.ready = Promise.resolve(module).then((module) => {
        this._html = module.html;
        this._svg = module.svg;
        this._render = module.render;
        this._Hole = module.Hole;
        this._unsafe = module.unsafe;
        return this;
      });
      return this.ready;
    },

    html(strings, ...values) {
      if (!this._html) throw new Error('uhtml is not ready');
      return this._html(strings, ...values);
    },

    // SVG 片段必須用 svg 標記：html 標記生成的元素帶 HTML 名稱空間，插進 <svg> 裡不會顯示。
    svg(strings, ...values) {
      if (!this._svg) throw new Error('uhtml is not ready');
      return this._svg(strings, ...values);
    },

    raw(markup) {
      if (!this._unsafe) throw new Error('uhtml is not ready');
      return this._unsafe(String(markup ?? ''));
    },

    get empty() {
      return null;
    },

    isTemplate(value) {
      return Boolean(this._Hole && value instanceof this._Hole);
    },

    render(view, container) {
      if (!container) return null;
      if (!this._render || !this._html) throw new Error('uhtml is not ready');
      const resolveContent = () => {
        const content = typeof view === 'function' ? view() : view;
        if (!this.isTemplate(content)) throw new TypeError('TemplateRenderer.render requires a template');
        return content;
      };
      const current = this._roots.get(container);
      let next = null;

      if (!current) {
        this._render(container, () => {
          next = resolveContent();
          return next;
        });
        this._roots.set(container, {hole: next});
        return container;
      }

      next = resolveContent();
      if (current.hole.t === next.t) {
        // uhtml 5.0.9 會快取 repeated render 傳入的新 Hole，複用舊 Hole 才能持續增量更新。
        current.hole.update(next);
      } else {
        this._render(container, () => next);
        current.hole = next;
      }
      return container;
    },

    renderHtml(markup, container) {
      return this.render(() => this.html`${this.raw(typeof markup === 'function' ? markup() : markup)}`, container);
    },

    clear(container) {
      return this.render(() => this.html``, container);
    }
  };

  // calculator-help-popover
  let helpPopoverSequence = 0;

  class CalculatorHelpPopover {
    constructor(ctx) {
      this.ctx = ctx;
    }

    mount({popup, title, heading, content}) {
      const {TemplateRenderer, utils} = this.ctx;
      const titleElement = popup.querySelector('.swal2-title');
      const container = popup.closest('.swal2-container');
      if (!titleElement || !container) return null;

      // 幫助提示浮層是跨模組共用的同一個元件，類名不帶模組字首；
      // 浮層 id 只用於 aria-controls 關聯，用遞增序號保證同頁多個彈窗不重號。
      const popoverId = `mst-help-popover-${++helpPopoverSequence}`;
      const miscSprite = utils.getSpriteUrl('misc') || '/static/media/misc_sprite.02869244.svg';
      const triggerHost = document.createElement('span');
      triggerHost.className = 'mst-help-anchor';
      TemplateRenderer.render(
        () => TemplateRenderer.html`
  <button type="button" class="mst-help-trigger" aria-haspopup="true" aria-expanded="false" aria-controls=${popoverId} title=${title}>
    <svg aria-hidden="true"><use href=${`${miscSprite}#info`}></use></svg>
  </button>
`,
        triggerHost
      );
      titleElement.appendChild(triggerHost);

      const popover = document.createElement('div');
      popover.id = popoverId;
      popover.className = 'mst-help-popover';
      popover.setAttribute('role', 'tooltip');
      TemplateRenderer.render(
        () => TemplateRenderer.html`
  <div class="mst-help-popover-title">${heading}</div>
  <div class="mst-help-popover-content"></div>
`,
        popover
      );
      popover.hidden = true;
      container.appendChild(popover);
      const trigger = triggerHost.querySelector('.mst-help-trigger');
      const contentElement = popover.querySelector('.mst-help-popover-content');
      const renderContent = (text) => {
        const paragraphs = String(text || '')
          .split(/\n+/)
          .filter(Boolean);
        TemplateRenderer.render(
          () => TemplateRenderer.html`
  ${paragraphs.map((paragraph) => TemplateRenderer.html`<div class="mst-help-popover-paragraph">${paragraph}</div>`)}
`,
          contentElement
        );
      };
      renderContent(content);

      const positionPopover = () => {
        if (popover.hidden) return;
        const viewport = window.visualViewport;
        const viewportLeft = viewport?.offsetLeft || 0;
        const viewportTop = viewport?.offsetTop || 0;
        const viewportRight = viewportLeft + (viewport?.width || window.innerWidth);
        const viewportBottom = viewportTop + (viewport?.height || window.innerHeight);
        const triggerRect = trigger.getBoundingClientRect();
        const popoverRect = popover.getBoundingClientRect();
        const margin = 8;
        const gap = 6;
        const left = Math.max(
          viewportLeft + margin,
          Math.min(triggerRect.left, viewportRight - popoverRect.width - margin)
        );
        const belowTop = triggerRect.bottom + gap;
        const top =
          belowTop + popoverRect.height <= viewportBottom - margin
            ? belowTop
            : Math.max(viewportTop + margin, triggerRect.top - popoverRect.height - gap);
        popover.style.left = `${left}px`;
        popover.style.top = `${top}px`;
      };
      const close = () => {
        popover.hidden = true;
        trigger.setAttribute('aria-expanded', 'false');
      };
      const onTriggerClick = (event) => {
        event.stopPropagation();
        popover.hidden = !popover.hidden;
        trigger.setAttribute('aria-expanded', String(!popover.hidden));
        if (!popover.hidden) positionPopover();
      };
      const onOutsidePointerDown = (event) => {
        if (!triggerHost.contains(event.target) && !popover.contains(event.target)) close();
      };
      triggerHost.addEventListener('pointerdown', (event) => event.stopPropagation());
      trigger.addEventListener('click', onTriggerClick);
      document.addEventListener('pointerdown', onOutsidePointerDown);
      window.addEventListener('resize', positionPopover);
      window.visualViewport?.addEventListener('resize', positionPopover);
      window.visualViewport?.addEventListener('scroll', positionPopover);

      return {
        setContent(text) {
          renderContent(text);
          positionPopover();
        },
        setError(isError) {
          popover.classList.toggle('mst-help-popover-error', isError);
          trigger.classList.toggle('mst-help-trigger-error', isError);
        },
        cleanup() {
          document.removeEventListener('pointerdown', onOutsidePointerDown);
          window.removeEventListener('resize', positionPopover);
          window.visualViewport?.removeEventListener('resize', positionPopover);
          window.visualViewport?.removeEventListener('scroll', positionPopover);
          TemplateRenderer.clear(triggerHost);
          triggerHost.remove();
          popover.remove();
        }
      };
    }
  }

  // clipboard-cart-import-feature
  class ClipboardCartImportFeature {
    constructor(ctx, Notifier) {
      this.ctx = ctx;
      this.Notifier = Notifier;
      this.panelRoot = null;
      this.panelObserver = null;
      this.bodyObserver = null;
    }

    parseClipboardCartText(text) {
      const replenish = {open: false, hour: 24};
      const lines = String(text || '')
        .split(/\r?\n/)
        .map((line) => line.trim())
        .filter(Boolean);
      const replenishMatch = lines[0]?.match(/^補充(?<days>\d+(?:\.\d+)?)天$/);
      if (replenishMatch) {
        replenish.open = true;
        replenish.hour = parseFloat(replenishMatch.groups.days) * 24;
        replenish.match = lines.shift();
      }

      const countFirstPattern =
        /^(?<limit>\+?)(?<count>\d+(?:\.\d+)?)(?<hour>\/h)?\s+(?<name>.+?)(?:\+(?<level>\d{0,2}))?$/i;
      const nameFirstPattern =
        /^(?<name>.+?)(?:\+(?<level>\d{0,2}))?\s+(?<limit>\+?)(?<count>\d+(?:\.\d+)?)(?<hour>\/h)?$/i;
      const items = [];
      for (const line of lines) {
        const match = line.match(countFirstPattern) || line.match(nameFirstPattern);
        if (!match?.groups) continue;
        const count = parseFloat(match.groups.count);
        const isHour = replenish.open || Boolean(match.groups.hour);
        items.push({
          match: line,
          name: match.groups.name,
          enhancementLevel: parseInt(match.groups.level || 0, 10),
          count,
          isLimit: !isHour && match.groups.limit === '+',
          isHour,
          quantity: isHour ? Math.ceil(replenish.hour * count) : count
        });
      }
      return {replenish, items};
    }

    async importFromClipboard() {
      const {DataHub, CharacterDataService, MarketMateBridge, i18n, utils} = this.ctx;
      const {Notifier} = this;
      try {
        if (!MarketMateBridge.isReady()) {
          Notifier.toast(i18n.t('marketMateUnavailable'), 'warning');
          return;
        }
        DataHub.initClientDataFromCache();
        DataHub.refreshI18nIndexes();
        const text = String((await utils.readClipboard()) || '').trim();
        if (!text) {
          Notifier.toast(i18n.t('toastImportClipboardEmpty'), 'error');
          return;
        }
        const result = this.parseClipboardCartText(text);
        const unmatched = [];
        const cartItems = [];
        for (const item of result.items) {
          const rawName = String(item.name || '').trim();
          let hrid = DataHub.ensureItemHrid(rawName) || '';
          if (hrid && !hrid.startsWith('/items/')) hrid = '/items/' + hrid;
          if (!hrid) {
            unmatched.push(rawName);
            continue;
          }
          let stock = 0;
          if (item.isLimit || item.isHour) {
            stock = CharacterDataService.getInventoryCount(hrid, item.enhancementLevel || 0);
          }
          const quantity = Math.ceil(Number(item.quantity - stock));
          if (!Number.isFinite(quantity) || quantity <= 0) continue;
          cartItems.push({
            itemId: hrid,
            name: DataHub.resolveItemName(hrid),
            iconRef: hrid,
            quantity,
            source: 'mst_clipboard'
          });
        }
        const response = cartItems.length ? MarketMateBridge.addToCart(cartItems) : {ok: true, added: 0, skipped: 0};
        if (!response?.ok) throw new Error(response?.error || i18n.t('marketMateUnavailable'));
        const added = response.added || 0;
        const quantitySum = cartItems.reduce((sum, item) => sum + item.quantity, 0);
        const parts = [];
        if (added) parts.push(i18n.t('toastImportClipboardDone', added, quantitySum.toLocaleString(i18n.locale)));
        if (unmatched.length) parts.push(i18n.t('toastImportClipboardUnmatched', unmatched.length));
        Notifier.toast(
          parts.length ? parts.join(i18n.t('messageSeparator')) : i18n.t('toastImportClipboardEmpty'),
          added ? 'success' : 'error'
        );
      } catch (error) {
        Notifier.toast(i18n.t('toastImportClipboardFailed', error?.message || error), 'error');
      }
    }

    getMarketMateRoot() {
      // 市場伴侶已整合進 MWITools，購物車面板宿主由 MWITools 建立。
      return document.getElementById('mwitools-procurement-host')?.shadowRoot || null;
    }

    addButton() {
      const {CONFIG, MarketMateBridge, i18n} = this.ctx;
      if (!CONFIG.isGameSite || !MarketMateBridge.isReady() || !this.panelRoot) return;
      // 匯入剪貼簿只屬於購物車清單頁；專案/設定等其他標籤頁不展示，並清掉可能殘留的舊按鈕。
      // MWITools 的 renderShell 會同步更新啟用標籤的 data-active，觀察器回撥讀取到的標籤狀態即為最終狀態。
      const activeTab = this.panelRoot.querySelector('.tab[data-active="true"]')?.dataset?.tab;
      if (activeTab !== 'cart') {
        this.panelRoot.querySelectorAll('#mst-mmm-import-clipboard').forEach((node) => node.remove());
        return;
      }
      const footer = this.panelRoot.querySelector('footer.panel-footer');
      if (!footer) return;
      const clearButton = footer.querySelector('button.clear');

      // 面板重繪可能重複觸發注入，只保留一個 MST 按鈕。
      const buttons = [
        ...this.panelRoot.querySelectorAll('#mst-mmm-import-clipboard')
      ];
      let button = buttons.shift();
      buttons.forEach((duplicate) => duplicate.remove());
      if (!button) {
        button = document.createElement('button');
        button.id = 'mst-mmm-import-clipboard';
        button.type = 'button';
        // MWITools 購物車面板在 shadowRoot 內，頁面樣式不可達，用內聯樣式與面板按鈕（清空/清空未收藏）協調。
        // 面板按鈕預設無邊框，MST 按鈕保持 1px 透明邊框佔位、懸停時才顯示邊框色，避免與面板按鈕觀感不一致。
        button.style.cssText =
          'margin-left:auto;padding:9px 18px;border:1px solid transparent;' +
          'border-radius:6px;background:rgba(231,231,231,0.08);color:#e7e7e7;' +
          'font-size:12.5px;font-weight:700;cursor:pointer;white-space:nowrap;';
        button.addEventListener('mouseenter', () => {
          button.style.borderColor = 'rgba(231,231,231,0.18)';
          button.style.background = 'rgba(231,231,231,0.16)';
        });
        button.addEventListener('mouseleave', () => {
          button.style.borderColor = 'transparent';
          button.style.background = 'rgba(231,231,231,0.08)';
        });
        button.addEventListener('click', (event) => {
          // 阻止 MWITools 腳部的事件委託處理 MST 自定義按鈕。
          event.stopPropagation();
          this.importFromClipboard();
        });
      }
      const label = i18n.t('importClipboard');
      if (button.textContent !== label) button.textContent = label;
      if (button.title !== label) button.title = label;

      // 有“清空”按鈕時插在它前面並清除自動左邊距；空清單時直接追加到腳部。
      if (clearButton) {
        clearButton.style.marginLeft = '0';
        if (button.nextElementSibling !== clearButton) clearButton.before(button);
      } else if (button.parentElement !== footer) {
        footer.append(button);
      }
    }

    connectPanelObserver() {
      const root = this.getMarketMateRoot();
      // 面板內部重繪由 panelObserver 負責；bodyObserver 只檢測宿主是否被替換。
      if (root === this.panelRoot) return;
      this.panelObserver?.disconnect();
      this.panelObserver = null;
      this.panelRoot = root;
      if (!root) return;

      // MWITools 會重繪清單腳部，需要在重繪後重新插入按鈕。
      this.panelObserver = new MutationObserver(() => this.addButton());
      this.panelObserver.observe(root, {childList: true, subtree: true});
      this.addButton();
    }

    updateButtonText() {
      const {i18n} = this.ctx;
      const button = this.panelRoot?.querySelector('#mst-mmm-import-clipboard');
      if (!button) return;
      button.textContent = i18n.t('importClipboard');
      button.title = i18n.t('importClipboard');
    }

    init() {
      const {CONFIG, MarketMateBridge, LanguageEvents, utils} = this.ctx;
      if (!CONFIG.isGameSite) return;
      MarketMateBridge.onReady(() => {
        if (!this.bodyObserver) this.bodyObserver = utils.observeBody(() => this.connectPanelObserver());
      });
      LanguageEvents.subscribe(() => this.updateButtonText());
    }
  }

  // swal-class-names
  const SWAL_CLASS_NAMES = {
    alert: {container: 'mst-swal2-theme', popup: 'mst-swal2-popup'},
    html: {container: 'mst-swal2-theme', popup: 'mst-swal2-popup mst-swal2-html-popup'}
  };

  // swal-dragging
  const swalDraggingMethods = {
    _enableBoundedDragging(popup) {
      if (!popup || popup._mstDragCleanup) return;
      const margin = 8;
      const clampPosition = (force) => {
        if (!force && !popup.classList.contains('swal2-dragging')) return;
        const viewport = window.visualViewport;
        const layoutWidth = Math.min(window.innerWidth, document.documentElement.clientWidth || window.innerWidth);
        const layoutHeight = Math.min(window.innerHeight, document.documentElement.clientHeight || window.innerHeight);
        const minX = Math.max(0, viewport?.offsetLeft || 0) + margin;
        const minY = Math.max(0, viewport?.offsetTop || 0) + margin;
        const maxX = Math.min(layoutWidth, viewport ? viewport.offsetLeft + viewport.width : layoutWidth) - margin;
        const maxY = Math.min(layoutHeight, viewport ? viewport.offsetTop + viewport.height : layoutHeight) - margin;
        const rect = popup.getBoundingClientRect();
        let deltaX = 0;
        let deltaY = 0;
        if (rect.left < minX) deltaX = minX - rect.left;
        else if (rect.right > maxX) deltaX = maxX - rect.right;
        if (rect.top < minY) deltaY = minY - rect.top;
        else if (rect.bottom > maxY) deltaY = maxY - rect.bottom;
        if (deltaX) {
          const current = parseFloat(popup.style.insetInlineStart) || 0;
          const rtlFactor = getComputedStyle(popup).direction === 'rtl' ? -1 : 1;
          popup.style.insetInlineStart = current + deltaX * rtlFactor + 'px';
        }
        if (deltaY) {
          const current = parseFloat(popup.style.insetBlockStart) || 0;
          popup.style.insetBlockStart = current + deltaY + 'px';
        }
      };
      const onDragEnd = (event) => {
        if (!popup.classList.contains('swal2-dragging')) return;
        const eventType = event?.type?.startsWith('touch') ? 'touchend' : 'mouseup';
        popup.dispatchEvent(new Event(eventType));
        clampPosition(true);
      };
      const onDragMove = (event) => {
        clampPosition(false);
        if (!popup.classList.contains('swal2-dragging')) return;
        const point = event.touches?.[0] || event;
        const viewport = window.visualViewport;
        const left = viewport?.offsetLeft || 0;
        const top = viewport?.offsetTop || 0;
        const right = viewport ? left + viewport.width : window.innerWidth;
        const bottom = viewport ? top + viewport.height : window.innerHeight;
        if (point.clientX <= left || point.clientX >= right - 1 || point.clientY <= top || point.clientY >= bottom - 1) {
          onDragEnd(event);
        }
      };
      const onViewportChange = () => clampPosition(true);
      const resizeObserver =
        typeof ResizeObserver === 'undefined'
          ? null
          : new ResizeObserver(() => {
              clampPosition(true);
            });
      resizeObserver?.observe(popup);
      document.body.addEventListener('mousemove', onDragMove);
      document.body.addEventListener('touchmove', onDragMove, {passive: true});
      document.body.addEventListener('mouseup', onDragEnd);
      document.body.addEventListener('touchend', onDragEnd);
      window.addEventListener('mouseup', onDragEnd);
      window.addEventListener('touchend', onDragEnd);
      document.addEventListener('mouseleave', onDragEnd);
      window.addEventListener('blur', onDragEnd);
      window.addEventListener('resize', onViewportChange);
      window.visualViewport?.addEventListener('resize', onViewportChange);
      window.visualViewport?.addEventListener('scroll', onViewportChange);
      popup._mstDragCleanup = () => {
        document.body.removeEventListener('mousemove', onDragMove);
        document.body.removeEventListener('touchmove', onDragMove);
        document.body.removeEventListener('mouseup', onDragEnd);
        document.body.removeEventListener('touchend', onDragEnd);
        window.removeEventListener('mouseup', onDragEnd);
        window.removeEventListener('touchend', onDragEnd);
        document.removeEventListener('mouseleave', onDragEnd);
        window.removeEventListener('blur', onDragEnd);
        window.removeEventListener('resize', onViewportChange);
        window.visualViewport?.removeEventListener('resize', onViewportChange);
        window.visualViewport?.removeEventListener('scroll', onViewportChange);
        resizeObserver?.disconnect();
        delete popup._mstDragCleanup;
      };
      popup._mstClampPosition = () => clampPosition(true);
      if (window.requestAnimationFrame) window.requestAnimationFrame(onViewportChange);
      else setTimeout(onViewportChange, 0);
    },

    _disableBoundedDragging(popup) {
      popup?._mstDragCleanup?.();
      delete popup?._mstClampPosition;
    }
  };

  // toast-notifier
  const toastNotifierMethods = {
    _toastPopup: null,
    _toastRoot: null,
    _toastPaused: false,
    _toastSequence: 0,
    _toastItems: [],

    _prefix(type) {
      return {success: '✅', error: '❌', warning: '⚠️', info: 'ℹ️', question: '❓'}[type] || '';
    },

    formatText(text, type) {
      const prefix = this._prefix(type);
      return prefix ? prefix + ' ' + String(text || '') : String(text || '');
    },

    _scheduleToast(item) {
      if (this._toastPaused || item.timerId || item.remaining <= 0) return;
      item.startedAt = Date.now();
      item.timerId = setTimeout(() => this._removeToast(item.id), item.remaining);
    },

    _pauseToasts() {
      if (this._toastPaused) return;
      this._toastPaused = true;
      this._toastItems.forEach((item) => {
        if (!item.timerId) return;
        clearTimeout(item.timerId);
        item.timerId = null;
        item.remaining = Math.max(0, item.remaining - (Date.now() - item.startedAt));
      });
    },

    _resumeToasts() {
      if (!this._toastPaused) return;
      this._toastPaused = false;
      this._toastItems.forEach((item) => this._scheduleToast(item));
    },

    _removeToast(id) {
      const index = this._toastItems.findIndex((item) => item.id === id);
      if (index === -1) return;
      const [
        item
      ] = this._toastItems.splice(index, 1);
      if (item.timerId) clearTimeout(item.timerId);
      this._renderToasts();
    },

    // SweetAlert2 同一例項只能顯示一個 popup。Toast 複用官方結構和主題類，
    // 但掛載到獨立容器，避免關閉或替換名片、房屋計算等 Swal 彈窗。
    _ensureToastHost() {
      if (this._toastPopup && document.contains(this._toastPopup)) return;
      const host = document.createElement('div');
      host.className = 'mst-swal-toast-host mst-swal2-theme';
      host.setAttribute('aria-live', 'polite');
      host.setAttribute('aria-atomic', 'false');
      const popup = document.createElement('div');
      popup.className = 'swal2-popup swal2-toast mst-swal2-toast';
      popup.setAttribute('role', 'status');
      const htmlContainer = document.createElement('div');
      htmlContainer.className = 'swal2-html-container';
      const stack = document.createElement('div');
      stack.className = 'mst-swal-toast-stack';
      htmlContainer.appendChild(stack);
      popup.appendChild(htmlContainer);
      host.appendChild(popup);
      document.body.appendChild(host);
      this._toastPopup = popup;
      this._toastRoot = stack;
      this._toastPopup.onmouseenter = () => this._pauseToasts();
      this._toastPopup.onmouseleave = () => this._resumeToasts();
    },

    _renderToasts() {
      if (!this._toastItems.length) {
        this._toastPopup?.closest('.mst-swal-toast-host')?.remove();
        this._toastPopup = null;
        this._toastRoot = null;
        this._toastPaused = false;
        return;
      }
      this._ensureToastHost();
      if (!this._toastRoot) return;
      const fragment = document.createDocumentFragment();
      this._toastItems.forEach((item) => {
        const element = document.createElement('div');
        element.className = 'mst-swal-toast-item';
        element.setAttribute('role', 'status');
        element.textContent = item.text;
        fragment.appendChild(element);
      });
      this._toastRoot.replaceChildren(fragment);
      this._toastItems.forEach((item) => this._scheduleToast(item));
    },

    toast(text, type = 'info') {
      const {CONFIG} = this.ctx;
      if (!text) return;
      if (typeof Swal === 'undefined') {
        console.warn('[MST]', text);
        return;
      }
      while (this._toastItems.length >= CONFIG.TOAST_MAX_COUNT) {
        const oldest = this._toastItems.shift();
        if (oldest?.timerId) clearTimeout(oldest.timerId);
      }
      const item = {
        id: ++this._toastSequence,
        text: this.formatText(text, type),
        remaining: CONFIG.TOAST_DURATION,
        startedAt: 0,
        timerId: null
      };
      this._toastItems.push(item);
      this._renderToasts();
    }
  };

  // swal-dialogs
  const swalDialogMethods = {
    // 標題行前置圖示：與工具箱選單一致，使用 misc 精靈圖片段。
    _mountTitleIcon(popup, icon) {
      const {TemplateRenderer, utils} = this.ctx;
      const titleElement = popup?.querySelector?.('.swal2-title');
      if (!titleElement || !icon) return;
      const miscSprite = utils?.getSpriteUrl?.('misc') || '/static/media/misc_sprite.02869244.svg';
      const host = document.createElement('span');
      host.className = 'mst-dialog-title-icon';
      TemplateRenderer.render(
        () => TemplateRenderer.html`<svg aria-hidden="true"><use href=${miscSprite + '#' + icon}></use></svg>`,
        host
      );
      titleElement.prepend(host);
    },

    alert(message, type = 'info', title = '') {
      const {i18n} = this.ctx;
      if (typeof Swal === 'undefined') {
        console.warn('[MST]', title, message);
        return Promise.resolve();
      }
      return Swal.fire({
        heightAuto: false,
        title: title || undefined,
        text: this.formatText(message, type),
        confirmButtonText: i18n.t('confirm'),
        draggable: true,
        customClass: this.SWAL_CLASS_NAMES.alert,
        didOpen: (popup) => this._enableBoundedDragging(popup),
        willClose: (popup) => this._disableBoundedDragging(popup)
      });
    },

    // 後續帶關閉按鈕的內容彈窗統一通過此入口建立。
    html({title, html: content, width = '48rem', popupClass = '', containerClass = '', icon = '', didOpen, willClose}) {
      const {TemplateRenderer} = this.ctx;
      if (typeof Swal === 'undefined') {
        console.warn('[MST]', title);
        return Promise.resolve();
      }
      const templateFactory =
        typeof content === 'function'
          ? content
          : TemplateRenderer.isTemplate(content)
            ? () => content
            : typeof content === 'string'
              ? () => TemplateRenderer.html`${TemplateRenderer.raw(content)}`
              : null;
      const templateRoot = templateFactory
        ? TemplateRenderer.render(templateFactory, document.createElement('div'))
        : null;
      return Swal.fire({
        heightAuto: false,
        title,
        html: templateRoot || content,
        width,
        showCloseButton: true,
        showConfirmButton: false,
        draggable: true,
        customClass: {
          container: [
            this.SWAL_CLASS_NAMES.html.container, containerClass
          ]
            .filter(Boolean)
            .join(' '),
          popup: [
            this.SWAL_CLASS_NAMES.html.popup, popupClass
          ]
            .filter(Boolean)
            .join(' ')
        },
        didOpen: (popup) => {
          this._enableBoundedDragging(popup);
          if (icon) this._mountTitleIcon(popup, icon);
          didOpen?.(popup);
        },
        willClose: (popup) => {
          willClose?.(popup);
          this._disableBoundedDragging(popup);
          if (templateRoot) TemplateRenderer.clear(templateRoot);
        }
      });
    }
  };

  // notifier
  class Notifier {
    constructor(ctx, classNames = SWAL_CLASS_NAMES) {
      this.ctx = ctx;
      this.SWAL_CLASS_NAMES = classNames;
      this._toastPopup = null;
      this._toastRoot = null;
      this._toastPaused = false;
      this._toastSequence = 0;
      this._toastItems = [];
      Object.assign(this, swalDraggingMethods, toastNotifierMethods, swalDialogMethods);
    }
  }

  // runtime-ui
  function installCommonUi(ctx) {
    const notifier = new Notifier(ctx, SWAL_CLASS_NAMES);

    ctx.SWAL_CLASS_NAMES = SWAL_CLASS_NAMES;
    ctx.Notifier = notifier;
    ctx.ClipboardCartImportFeature = ClipboardCartImportFeature;
    ctx.CalculatorHelpPopover = new CalculatorHelpPopover(ctx);
  }

  // ability-upgrade-presets
  // 技能及順序同步自 references/external-tools/mwi-tool/resources 下各職業的 equipmentPlan 配置。
